                  </IonSelect>
                </div>
                : <IonItem><IonLabel>No hay productos disponibles. Agregue productos para ofrecer recompensas.</IonLabel></IonItem>
              )}

              <IonItem lines="none" className="ion-no-padding wizard-field-group">
                <IonLabel className="ion-text-wrap">Activo</IonLabel>
                <IonToggle
                  checked={formState.isActive}
                  onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormState(p => ({ ...p, isActive: e.detail.checked }))}
                  slot="end"
                />
              </IonItem>

              <div className="wizard-field-group">
                <IonTextarea
                  fill="outline"
                  label="Descripción"
                  labelPlacement="floating"
                  value={formState.description}
                  onIonInput={(e: CustomEvent<TextareaInputEventDetail>) => setFormState(p => ({ ...p, description: e.detail.value as string }))}
                  rows={3}
                />
              </div>
            </div>

            <IonButton expand="block" onClick={handleSave} disabled={saving} className="ion-margin-top">
              {saving ? <IonSpinner name="dots" /> : (isEditing ? 'Actualizar' : 'Crear')}
            </IonButton>
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={showAlert}
          onDidDismiss={() => setShowAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Está seguro de que desea eliminar el elemento del catálogo "${itemToDelete?.name}"?`}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: handleConfirmDelete, cssClass: 'danger' }
          ]}
        />

        <IonToast
          isOpen={showToast}
          message={toastMessage}
          duration={2000}
          onDidDismiss={() => setShowToast(false)}
          color="success"
        />
      </IonContent>
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
